use serde_json::json;
use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fs,io::Read,path::Path,process::{Command,Stdio}};
use std::os::unix::fs::FileTypeExt;
fn hash(p:&Path)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn copy(src:&Path,dst:&Path,root:&Path,index:&mut BTreeMap<String,String>){assert!(src.symlink_metadata().unwrap().file_type().is_file(),"nonregular {}",src.display());fs::create_dir_all(dst.parent().unwrap()).unwrap();let expected=if src.file_name().is_some_and(|n|n=="perf.data"){
let before=fs::metadata(src).unwrap();let out=Command::new("sudo").args(["-n","sha256sum"]).arg(src).output().unwrap();assert!(out.status.success());let digest=String::from_utf8(out.stdout).unwrap().split_whitespace().next().unwrap().to_owned();let file=fs::File::create(dst).unwrap();assert!(Command::new("sudo").args(["-n","cat"]).arg(src).stdout(Stdio::from(file)).status().unwrap().success());let after=fs::metadata(src).unwrap();assert_eq!(before.len(),after.len());assert_eq!(before.modified().unwrap(),after.modified().unwrap());digest
}else{fs::copy(src,dst).unwrap();hash(src)};assert_eq!(hash(dst),expected);assert!(index.insert(dst.strip_prefix(root).unwrap().to_str().unwrap().into(),expected).is_none());}
fn tree(src:&Path,dst:&Path,root:&Path,index:&mut BTreeMap<String,String>){let mut paths=fs::read_dir(src).unwrap().map(|e|e.unwrap().path()).collect::<Vec<_>>();paths.sort();for p in paths{let name=p.file_name().unwrap();if name=="target"{continue}let d=dst.join(name);let kind=p.symlink_metadata().unwrap().file_type();if kind.is_dir(){tree(&p,&d,root,index)}else if kind.is_fifo(){assert!(["ctl","ack"].iter().any(|n|name==*n));}else if name!="candidate-sdk"{copy(&p,&d,root,index);}}}
fn main(){let src=Path::new("/tmp/zopro-retained-deque-buffers");let report=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-retained-deque-buffers");let dst=report.join("artifacts");assert!(!dst.exists());let mut index=BTreeMap::new();
for name in ["experiment.json","accepted-manifest.json","prepare.json","prepare-v2.json","native-plan.json","native-plan-v2.json","build-input-pins.json","build-input-pins-v2.json","native.log","native-v2.log","implement.rs","prepare-build.rs","prepare-build-v2.rs","repair-build.rs","failure-v1.json","model-tests.log","model-lock.log","deque-lock.log","rayon-lock.log","upstream-deque.rs","upstream-pins.json","lock-audit.json","patch-anchors.json","source-audit.rs","source-audit.json","source.patch","steal-disassembly.txt","codegen-review.json","registry-audit.rs","registry-audit.json","registry-input-pins.json","prepare-protocol-source.rs","make-protocol.rs","make-protocol.log","linked-scheduler-libraries.json","all-nine-template.json","perf-template.json","perf-template-with-pins.json","perf-plan.json","input-pins.json","preflight-plan.json","inventory-preflight.sh","validate-preflight.jq","preflight-validation.json","preflight-proof-inventory.json","preflight.log","perf.log","analyze.rs","analyze-tests.log","pilot-result.json","trace-build-plan.json","trace-build.log","prepare-trace.rs","trace-plan.json","trace-input-pins.json","trace-template.json","inventory-trace.sh","validate-trace.jq","trace-validation.json","trace-proof-inventory.json","trace.log","analyze-trace.rs","trace-result.json","closeout.rs","closeout-initial.rs","closeout-initial-failure.log","closeout.json","proof-inventory.json","next-design.md","write-report.rs","work-state.json","publish.rs"]{copy(&src.join(name),&dst.join(name),&dst,&mut index)}
for name in ["candidate-v2","overlay","upstream","upstream-v2","model","model-v2","native","native-v2","preflight","preflight-proofs","perf","trace-build","trace","trace-proofs"]{tree(&src.join(name),&dst.join(name),&dst,&mut index)}
let raw=index.keys().filter(|p|p.ends_with("/perf.data")).count();let symbols=index.keys().filter(|p|p.ends_with("/symbols/stdout.log")).count();assert_eq!(raw,9);assert_eq!(symbols,9);let member=|p:&&String|p.ends_with(".proof")||p.ends_with(".public");let members=index.keys().filter(|p|(p.starts_with("perf/")||p.starts_with("preflight-proofs/")||p.starts_with("trace-proofs/"))&&member(p)).count();let fixtures=index.keys().filter(|p|p.starts_with("candidate-v2/")&&member(p)).count();assert_eq!(members,510);assert_eq!(fixtures,2);
let sums=index.iter().map(|(p,h)|format!("{h}  {p}\n")).collect::<String>();fs::write(dst.join("SHA256SUMS"),sums).unwrap();fs::write(dst.join("artifact-index.json"),format!("{}\n",serde_json::to_string_pretty(&json!({"files":index.len(),"proof_public_members":members,"additional_source_fixture_members":fixtures,"raw_perf":raw,"expanded_symbols":symbols,"sha256":index,"scope":"Archived source/config/test/proof/measurement copies. Nine raw captures and nine expanded streams retained locally and ignored from Git. Executables/compiler caches represented by exact source/build/link/failure hash receipts. Initial overlay/model/upstream sources and compile failures preserved; final prepared source is candidate-v2."})).unwrap())).unwrap();fs::write(report.join(".gitignore"),"/artifacts/**/perf.data\n/artifacts/**/symbols/stdout.log\n").unwrap();fs::write(report.join(".gitattributes"),"# Preserve the bytes of archived output and pinned source.\nartifacts/** -whitespace\n").unwrap();println!("ARCHIVE_VERIFIED {} files,510 new proof/public members,2 source fixtures,9 raw/9 expanded streams",index.len());}
